/*
 * Obsidian-style graph view for the wiki.
 *
 * Reads the data generated by layouts/index.graph.json and renders it as a
 * force-directed graph on a canvas. No external dependencies.
 */
(function () {
  "use strict";

  var TAU = Math.PI * 2;

  // --- simulation constants ---------------------------------------------
  var ALPHA_DECAY = 0.018;   // how fast the layout cools down
  var ALPHA_MIN = 0.0015;    // below this the simulation is considered settled
  var VELOCITY_DECAY = 0.62; // friction
  var CHARGE = -260;         // node repulsion (negative = push apart)
  var LINK_DISTANCE = 42;
  var LINK_STRENGTH = 0.55;
  var REF_DISTANCE = 70;     // real cross references sit a bit further apart
  var GRAVITY = 0.045;

  function boot(root) {
    var canvas = root.querySelector(".wiki-graph__canvas");
    var status = root.querySelector(".wiki-graph__status");
    var ctx = canvas.getContext("2d");

    fetch(root.dataset.src, { credentials: "same-origin" })
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.json();
      })
      .then(function (data) {
        if (status) status.remove();
        render(root, canvas, ctx, data);
      })
      .catch(function (err) {
        if (status) status.textContent = "Graph konnte nicht geladen werden (" + err.message + ").";
      });
  }

  function render(root, canvas, ctx, data) {
    var nodes = data.nodes.map(function (n, i) {
      return {
        i: i,
        title: n.title,
        url: n.url,
        group: n.group,
        section: n.section,
        words: n.words || 0,
        deg: 0,
        x: 0, y: 0, vx: 0, vy: 0,
        fx: null, fy: null
      };
    });

    var links = data.links.map(function (l) {
      var s = nodes[l.source];
      var t = nodes[l.target];
      s.deg++;
      t.deg++;
      return { s: s, t: t, ref: l.kind === "ref" };
    });

    // adjacency, used for hover highlighting
    var neighbours = nodes.map(function () { return []; });
    links.forEach(function (l) {
      neighbours[l.s.i].push(l.t.i);
      neighbours[l.t.i].push(l.s.i);
    });

    // link strength is softened for well connected nodes, like d3-force does
    links.forEach(function (l) {
      var total = l.s.deg + l.t.deg;
      l.bias = l.s.deg / total;
      l.strength = LINK_STRENGTH / Math.min(l.s.deg, l.t.deg);
      l.distance = l.ref ? REF_DISTANCE : LINK_DISTANCE;
    });

    // colour per top level section, spread over the hue circle
    var groups = [];
    nodes.forEach(function (n) {
      if (groups.indexOf(n.group) === -1) groups.push(n.group);
    });
    groups.sort();
    var colours = {};
    groups.forEach(function (g, i) {
      colours[g] = "hsl(" + Math.round((i * 137.508) % 360) + " 62% 55%)";
    });

    // phyllotaxis start positions keep the first ticks from collapsing
    nodes.forEach(function (n, i) {
      var r = 12 * Math.sqrt(i + 0.5);
      var a = i * 2.399963;
      n.x = r * Math.cos(a);
      n.y = r * Math.sin(a);
    });

    var view = { k: 1, x: 0, y: 0 };
    var alpha = 1;
    var running = true;
    var fitted = false;
    var hovered = null;
    var dragNode = null;
    var panning = false;
    var pointer = { x: 0, y: 0, down: null, moved: false };
    var showTree = true;
    var query = "";
    var activeGroup = null;
    var width = 0, height = 0, dpr = 1;

    function radius(n) {
      return 2.6 + Math.sqrt(n.deg) * 1.5 + (n.section ? 1.2 : 0);
    }

    function matches(n) {
      if (activeGroup && n.group !== activeGroup) return false;
      if (query && n.title.toLowerCase().indexOf(query) === -1) return false;
      return true;
    }

    // ---- simulation ----------------------------------------------------
    function tick() {
      var i, j, a, b, dx, dy, d2, d, w;

      for (i = 0; i < nodes.length; i++) {
        a = nodes[i];
        for (j = i + 1; j < nodes.length; j++) {
          b = nodes[j];
          dx = b.x - a.x;
          dy = b.y - a.y;
          d2 = dx * dx + dy * dy;
          if (d2 < 1) {
            // jitter coincident nodes apart
            dx = (Math.random() - 0.5) * 2;
            dy = (Math.random() - 0.5) * 2;
            d2 = dx * dx + dy * dy || 1;
          }
          w = (CHARGE * alpha) / d2;
          a.vx += dx * w;
          a.vy += dy * w;
          b.vx -= dx * w;
          b.vy -= dy * w;
        }
      }

      for (i = 0; i < links.length; i++) {
        var l = links[i];
        dx = l.t.x + l.t.vx - l.s.x - l.s.vx;
        dy = l.t.y + l.t.vy - l.s.y - l.s.vy;
        d = Math.sqrt(dx * dx + dy * dy) || 1;
        w = ((d - l.distance) / d) * alpha * l.strength;
        dx *= w;
        dy *= w;
        l.t.vx -= dx * l.bias;
        l.t.vy -= dy * l.bias;
        l.s.vx += dx * (1 - l.bias);
        l.s.vy += dy * (1 - l.bias);
      }

      for (i = 0; i < nodes.length; i++) {
        a = nodes[i];
        a.vx -= a.x * GRAVITY * alpha;
        a.vy -= a.y * GRAVITY * alpha;

        if (a.fx !== null) {
          a.x = a.fx;
          a.y = a.fy;
          a.vx = a.vy = 0;
        } else {
          a.vx *= VELOCITY_DECAY;
          a.vy *= VELOCITY_DECAY;
          a.x += a.vx;
          a.y += a.vy;
        }
      }

      alpha -= alpha * ALPHA_DECAY;
    }

    function reheat(value) {
      alpha = Math.max(alpha, value || 0.35);
      if (!running) {
        running = true;
        requestAnimationFrame(frame);
      }
    }

    // Zoom and pan so the whole graph is visible.
    function fitView() {
      if (!width || !height) return;
      var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      for (var i = 0; i < nodes.length; i++) {
        var n = nodes[i];
        var r = radius(n);
        if (n.x - r < minX) minX = n.x - r;
        if (n.y - r < minY) minY = n.y - r;
        if (n.x + r > maxX) maxX = n.x + r;
        if (n.y + r > maxY) maxY = n.y + r;
      }
      if (!isFinite(minX)) return;
      // leave room for the toolbar on top and the legend at the bottom
      var padX = 32, padTop = 52, padBottom = 64;
      var k = Math.min(
        (width - padX * 2) / Math.max(1, maxX - minX),
        (height - padTop - padBottom) / Math.max(1, maxY - minY)
      );
      view.k = Math.min(2.5, Math.max(0.1, k));
      view.x = width / 2 - ((minX + maxX) / 2) * view.k;
      view.y = (padTop + height - padBottom) / 2 - ((minY + maxY) / 2) * view.k;
    }

    // ---- drawing -------------------------------------------------------
    function css(name) {
      return getComputedStyle(root).getPropertyValue(name).trim();
    }

    function draw() {
      var colLink = css("--wg-link");
      var colRef = css("--wg-link-ref");
      var colActive = css("--wg-link-active");
      var colDim = css("--wg-dim");
      var colLabel = css("--wg-label");
      var colLabelActive = css("--wg-label-active");
      var bg = css("--wg-bg");

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, width, height);
      ctx.translate(view.x, view.y);
      ctx.scale(view.k, view.k);

      var near = null;
      if (hovered !== null) {
        near = Object.create(null);
        near[hovered] = true;
        neighbours[hovered].forEach(function (n) { near[n] = true; });
      }

      // links
      ctx.lineWidth = 1 / view.k;
      for (var i = 0; i < links.length; i++) {
        var l = links[i];
        if (!l.ref && !showTree) continue;
        var lit = near && (near[l.s.i] && near[l.t.i]);
        var faded = (near && !lit) || (!matches(l.s) && !matches(l.t));
        ctx.strokeStyle = faded ? colDim : (lit ? colActive : (l.ref ? colRef : colLink));
        ctx.lineWidth = (lit ? 2 : l.ref ? 1.4 : 1) / view.k;
        ctx.beginPath();
        ctx.moveTo(l.s.x, l.s.y);
        ctx.lineTo(l.t.x, l.t.y);
        ctx.stroke();
      }

      // nodes
      for (var n, k = 0; k < nodes.length; k++) {
        n = nodes[k];
        var r = radius(n);
        var lit2 = near ? !!near[n.i] : true;
        var on = matches(n) && lit2;
        ctx.globalAlpha = on ? 1 : 0.18;
        ctx.fillStyle = colours[n.group];
        ctx.beginPath();
        ctx.arc(n.x, n.y, r, 0, TAU);
        ctx.fill();
        if (n.i === hovered) {
          ctx.globalAlpha = 1;
          ctx.strokeStyle = colLabelActive;
          ctx.lineWidth = 1.5 / view.k;
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;

      // labels: always for the hover neighbourhood and for search hits,
      // otherwise only once zoomed in far enough to stay readable
      var showAll = view.k > 1.35;
      var fontSize = Math.max(9, 11 / view.k);
      ctx.font = fontSize + "px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      for (var m = 0; m < nodes.length; m++) {
        var p = nodes[m];
        var isNear = near && near[p.i];
        var isHit = (query || activeGroup) && matches(p);
        if (!isNear && !isHit && !(showAll && !near)) continue;
        if (!isNear && !isHit && !matches(p)) continue;
        ctx.fillStyle = isNear || isHit ? colLabelActive : colLabel;
        ctx.fillText(p.title, p.x, p.y + radius(p) + 2.5 / view.k);
      }
    }

    function frame() {
      if (alpha > ALPHA_MIN) {
        tick();
      } else {
        running = false;
        if (!fitted) {
          fitted = true;
          fitView();
        }
      }
      draw();
      if (running) requestAnimationFrame(frame);
    }

    // ---- interaction ---------------------------------------------------
    function resize() {
      var rect = canvas.getBoundingClientRect();
      dpr = window.devicePixelRatio || 1;
      width = rect.width;
      height = rect.height;
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      if (!view.x && !view.y) {
        view.x = width / 2;
        view.y = height / 2;
      }
      draw();
    }

    function toWorld(ev) {
      var rect = canvas.getBoundingClientRect();
      return {
        x: (ev.clientX - rect.left - view.x) / view.k,
        y: (ev.clientY - rect.top - view.y) / view.k
      };
    }

    function pick(p) {
      var best = null;
      var bestDist = Infinity;
      for (var i = 0; i < nodes.length; i++) {
        var n = nodes[i];
        if (!matches(n)) continue;
        var dx = n.x - p.x;
        var dy = n.y - p.y;
        var d = dx * dx + dy * dy;
        var r = radius(n) + 4 / view.k;
        if (d < r * r && d < bestDist) {
          bestDist = d;
          best = n;
        }
      }
      return best;
    }

    canvas.addEventListener("pointermove", function (ev) {
      var p = toWorld(ev);
      if (dragNode) {
        dragNode.fx = p.x;
        dragNode.fy = p.y;
        pointer.moved = true;
        reheat(0.3);
        return;
      }
      if (panning) {
        view.x += ev.clientX - pointer.x;
        view.y += ev.clientY - pointer.y;
        pointer.x = ev.clientX;
        pointer.y = ev.clientY;
        pointer.moved = true;
        draw();
        return;
      }
      var hit = pick(p);
      var next = hit ? hit.i : null;
      canvas.classList.toggle("is-over-node", !!hit);
      if (next !== hovered) {
        hovered = next;
        if (!running) draw();
      }
    });

    canvas.addEventListener("pointerdown", function (ev) {
      canvas.setPointerCapture(ev.pointerId);
      pointer.x = ev.clientX;
      pointer.y = ev.clientY;
      pointer.moved = false;
      var hit = pick(toWorld(ev));
      if (hit) {
        dragNode = hit;
        hit.fx = hit.x;
        hit.fy = hit.y;
        reheat(0.3);
      } else {
        panning = true;
        canvas.classList.add("is-dragging");
      }
    });

    function endPointer(ev) {
      if (dragNode && !pointer.moved) {
        window.location.href = dragNode.url;
      }
      if (dragNode) {
        dragNode.fx = null;
        dragNode.fy = null;
        dragNode = null;
        reheat(0.2);
      }
      panning = false;
      canvas.classList.remove("is-dragging");
      if (ev && ev.pointerId !== undefined && canvas.hasPointerCapture(ev.pointerId)) {
        canvas.releasePointerCapture(ev.pointerId);
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);
    canvas.addEventListener("pointerleave", function () {
      if (hovered !== null) {
        hovered = null;
        if (!running) draw();
      }
    });

    canvas.addEventListener("wheel", function (ev) {
      ev.preventDefault();
      var rect = canvas.getBoundingClientRect();
      var mx = ev.clientX - rect.left;
      var my = ev.clientY - rect.top;
      var factor = Math.exp(-ev.deltaY * 0.0015);
      var k = Math.min(6, Math.max(0.15, view.k * factor));
      view.x = mx - ((mx - view.x) / view.k) * k;
      view.y = my - ((my - view.y) / view.k) * k;
      view.k = k;
      draw();
    }, { passive: false });

    // ---- controls ------------------------------------------------------
    var search = root.querySelector(".wiki-graph__search");
    if (search) {
      search.addEventListener("input", function () {
        query = search.value.trim().toLowerCase();
        draw();
      });
    }

    var treeToggle = root.querySelector(".wiki-graph__tree");
    if (treeToggle) {
      treeToggle.addEventListener("change", function () {
        showTree = treeToggle.checked;
        draw();
      });
    }

    var resetBtn = root.querySelector(".wiki-graph__reset");
    if (resetBtn) {
      resetBtn.addEventListener("click", function () {
        nodes.forEach(function (n) { n.fx = n.fy = null; });
        fitted = false;
        alpha = 1;
        warmUp();
        fitView();
        reheat(0.25);
        draw();
      });
    }

    var legend = root.querySelector(".wiki-graph__legend");
    if (legend) {
      groups.forEach(function (g) {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.setAttribute("aria-pressed", "false");
        btn.style.color = colours[g];
        btn.innerHTML = '<span class="dot"></span>';
        btn.appendChild(document.createTextNode(g || "docs"));
        btn.addEventListener("click", function () {
          activeGroup = activeGroup === g ? null : g;
          Array.prototype.forEach.call(legend.children, function (el) {
            el.setAttribute("aria-pressed", String(el === btn && activeGroup === g));
          });
          draw();
        });
        legend.appendChild(btn);
      });
    }

    new MutationObserver(function () { draw(); })
      .observe(document.documentElement, { attributes: true, attributeFilter: ["data-dark-mode"] });

    function warmUp() {
      var target = Math.pow(1 - ALPHA_DECAY, 260);
      while (alpha > target) tick();
    }

    window.addEventListener("resize", resize);
    resize();
    warmUp();
    fitView();
    draw();
    requestAnimationFrame(frame);
  }

  function init() {
    Array.prototype.forEach.call(document.querySelectorAll(".wiki-graph"), boot);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
